<script setup lang="ts">
import type { Artifact } from '~/composables/useManager'
const manager = useManager()
const { models, artifacts, canOperate } = manager
const busy = ref(false)
const message = ref('')
const artifactForm = reactive({ path: '', display_name: '' })
const modelForm = reactive({ model_id: '', display_name: '', artifact_id: '', always_on: false, autoload_enabled: true, priority: 'normal', routing_policy: 'least_active' })
async function registerArtifact() { busy.value = true; message.value = ''; try { const artifact = await manager.request<Artifact>('/api/v1/artifacts/register', { method: 'POST', body: artifactForm }); artifactForm.path = ''; artifactForm.display_name = ''; modelForm.artifact_id = artifact.id; await manager.refresh() } catch (error: any) { message.value = error?.data?.error || error?.message || 'Unable to register artifact' } finally { busy.value = false } }
async function createModel() { busy.value = true; message.value = ''; try { await manager.request('/api/v1/models', { method: 'POST', body: modelForm }); modelForm.model_id = ''; modelForm.display_name = ''; await manager.refresh() } catch (error: any) { message.value = error?.data?.error || error?.message || 'Unable to create model' } finally { busy.value = false } }
async function action(id: string, action: 'start' | 'stop') { busy.value = true; message.value = ''; try { await manager.request(`/api/v1/models/${id}/${action}`, { method: 'POST' }); await manager.refresh() } catch (error: any) { message.value = error?.data?.error || error?.message || `Unable to ${action} model` } finally { busy.value = false } }
async function remove(id: string) { if (!confirm('Delete this model configuration? The GGUF file will not be deleted.')) return; busy.value = true; try { await manager.request(`/api/v1/models/${id}`, { method: 'DELETE' }); await manager.refresh() } catch (error: any) { message.value = error?.data?.error || error?.message || 'Unable to delete model' } finally { busy.value = false } }
</script>

<template>
  <div><header class="page-header"><div><p class="eyebrow">MODEL REGISTRY</p><h1>Models</h1><p class="muted">Register local GGUF files and control model workers.</p></div><button class="ghost" @click="manager.refresh">Refresh</button></header><p v-if="message" class="alert error">{{ message }}</p><div class="content-grid"><section class="panel grow-panel"><div class="panel-header"><div><p class="eyebrow">CONFIGURED</p><h2>Model fleet</h2></div></div><div v-if="!models.length" class="empty-state"><strong>No models configured</strong><p>Create your first model using a registered artifact.</p></div><article v-for="model in models" :key="model.id" class="model-row"><div class="model-main"><div class="model-title"><strong>{{ model.model_id }}</strong><span class="status" :data-state="manager.modelState(model)">{{ manager.modelState(model) }}</span></div><p>{{ model.display_name || model.artifact_path }}</p><small>{{ model.priority }} · {{ model.routing_policy }} · {{ model.always_on ? 'always on' : model.autoload_enabled ? 'autoload' : 'manual' }}</small></div><div v-if="canOperate" class="row-actions"><button class="ghost small" :disabled="busy" @click="action(model.id, 'start')">Start</button><button class="ghost small" :disabled="busy" @click="action(model.id, 'stop')">Stop</button><button class="danger small" :disabled="busy" @click="remove(model.id)">Delete</button></div></article></section><div v-if="canOperate" class="side-stack"><section class="panel"><p class="eyebrow">LOCAL ARTIFACT</p><h2>Register GGUF</h2><p class="muted">The file must exist inside the backend models volume.</p><form @submit.prevent="registerArtifact"><label>GGUF path<input v-model="artifactForm.path" placeholder="/models/qwen.gguf" required></label><label>Display name<input v-model="artifactForm.display_name" placeholder="Optional"></label><button class="primary" :disabled="busy">Register artifact</button></form></section><section class="panel"><p class="eyebrow">NEW MODEL</p><h2>Create model</h2><form @submit.prevent="createModel"><label>Public model ID<input v-model="modelForm.model_id" placeholder="qwen-coder" required></label><label>Display name<input v-model="modelForm.display_name" placeholder="Optional"></label><label>Artifact<select v-model="modelForm.artifact_id" required><option value="" disabled>Select artifact</option><option v-for="artifact in artifacts" :key="artifact.id" :value="artifact.id">{{ artifact.display_name }}{{ artifact.quantization ? ` · ${artifact.quantization}` : '' }}</option></select></label><div class="field-row"><label>Priority<select v-model="modelForm.priority"><option value="low">Low</option><option value="normal">Normal</option><option value="high">High</option></select></label><label>Routing<select v-model="modelForm.routing_policy"><option value="least_active">Least active</option><option value="round_robin">Round robin</option></select></label></div><label class="check"><input v-model="modelForm.autoload_enabled" type="checkbox"> Autoload on request</label><label class="check"><input v-model="modelForm.always_on" type="checkbox"> Always on</label><button class="primary" :disabled="busy || !artifacts.length">Create model</button></form></section></div></div></div>
</template>
